# -*- coding: utf-8 -*-
"""
=============================================================================
COLÉGIO PEDRO II - SISTEMA WEB DE LANÇAMENTO DA 2ª CERTIFICAÇÃO
=============================================================================
Aplicação Web completa para navegadores (Chrome, Edge, Safari, Firefox).
Permite acesso simultâneo de professores de qualquer computador ou celular.
Hospedagem gratuita via Streamlit Community Cloud (ou execução local).
=============================================================================
"""

import streamlit as st
import pandas as pd
import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
from openpyxl.utils import get_column_letter
import io
import json
import zlib
import base64

# Configuração da Página Web
st.set_page_config(
    page_title="Colégio Pedro II - Lançamento 2ª Certificação",
    page_icon="🎓",
    layout="wide",
    initial_sidebar_state="expanded"
)

# Base de Dados Compactada das 38 Turmas Oficiais
B64_DATA = ""

@st.cache_data
def carregar_dados_turmas():
    compressed_bytes = base64.b64decode(B64_DATA)
    json_bytes = zlib.decompress(compressed_bytes)
    return json.loads(json_bytes.decode('utf-8'))

turmas_data = carregar_dados_turmas()
turmas_keys = sorted(list(turmas_data.keys()))

def calc_nota_minima(n1):
    if n1 is None or str(n1).strip() in ["(*)", "", "None"]:
        return 6.0
    try:
        val = float(n1)
        meta = (30.0 - 2.0 * val) / 3.0
        return max(0.0, round(meta, 1))
    except (ValueError, TypeError):
        return 6.0

def calc_media_final(n1, n2):
    try:
        val1 = float(n1)
        val2 = float(n2)
        return round((val1 * 2.0 + val2 * 3.0) / 5.0, 1)
    except (ValueError, TypeError):
        return None

def gerar_planilha_2_colunas(tcode, dcode, results):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Lançamento 2ª Certificação"
    ws.sheet_view.showGridLines = True

    navy_fill = PatternFill(start_color="2F5496", end_color="2F5496", fill_type="solid")
    blue_header_fill = PatternFill(start_color="4472C4", end_color="4472C4", fill_type="solid")
    input_fill = PatternFill(start_color="DCE6F1", end_color="DCE6F1", fill_type="solid")

    font_title = Font(name="Calibri", size=12, bold=True, color="FFFFFF")
    font_header = Font(name="Calibri", size=11, bold=True, color="FFFFFF")
    font_data = Font(name="Calibri", size=11)

    thin_border = Border(
        left=Side(style='thin', color='D9D9D9'), right=Side(style='thin', color='D9D9D9'),
        top=Side(style='thin', color='D9D9D9'), bottom=Side(style='thin', color='D9D9D9')
    )

    ws.cell(row=1, column=1, value="COLÉGIO PEDRO II - PLANILHA DE LANÇAMENTO DA 2ª CERTIFICAÇÃO").font = font_title
    ws.cell(row=1, column=1).fill = navy_fill
    ws.merge_cells('A1:B1')

    ws.cell(row=2, column=1, value=f"TURMA: {tcode} | DISCIPLINA: {dcode}").font = font_title
    ws.cell(row=2, column=1).fill = blue_header_fill
    ws.merge_cells('A2:B2')

    ws.cell(row=4, column=1, value="Nº").font = font_header
    ws.cell(row=4, column=1).fill = navy_fill
    ws.cell(row=4, column=1).alignment = Alignment(horizontal="center")

    ws.cell(row=4, column=2, value=dcode).font = font_header
    ws.cell(row=4, column=2).fill = navy_fill
    ws.cell(row=4, column=2).alignment = Alignment(horizontal="center")

    for i, res in enumerate(results, 5):
        c1 = ws.cell(row=i, column=1, value=res['num'])
        c1.font = font_data
        c1.alignment = Alignment(horizontal="center")
        c1.border = thin_border

        val2 = res['n2']
        c2 = ws.cell(row=i, column=2, value=val2 if val2 != "(*)" else "(*)")
        c2.font = font_data
        c2.fill = input_fill
        c2.alignment = Alignment(horizontal="center")
        c2.border = thin_border
        if isinstance(val2, (int, float)):
            c2.number_format = '0.0'

    ws.column_dimensions['A'].width = 10
    ws.column_dimensions['B'].width = 18

    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    return output

# Barra Superior / Título
st.title("🎓 Colégio Pedro II — Lançamento da 2ª Certificação")
st.markdown("##### Sistema Web para Docentes • Cálculo Dinâmico de Metas e Média Final")
st.write("---")

# Barra Lateral (Filtros e Configurações)
with st.sidebar:
    st.header("⚙️ Painel do Docente")
    turma_selecionada = st.selectbox("Selecione a Turma:", turmas_keys, index=0)
    
    disciplinas_da_turma = turmas_data[turma_selecionada]["subjects"]
    disciplina_selecionada = st.selectbox("Selecione a Disciplina:", disciplinas_da_turma, index=0)
    
    st.write("---")
    st.subheader("📂 Importação de Notas")
    uploaded_file = st.file_uploader("Carregar planilha própria (.xlsx / .csv):", type=["xlsx", "xls", "csv"])
    
    st.write("---")
    st.info("💡 **Regra de Média Ponderada**:\n(N1 × 2 + N2 × 3) / 5 ≥ 6,0\nArredondamento em 1 casa decimal.")

# Importação de Planilha Externa
imported_grades = {}
if uploaded_file is not None:
    try:
        if uploaded_file.name.endswith('.csv'):
            df_imp = pd.read_csv(uploaded_file)
        else:
            df_imp = pd.read_excel(uploaded_file)
        
        # Procura coluna de número e nota
        for _, row in df_imp.iterrows():
            vals = list(row.values)
            if len(vals) >= 2:
                try:
                    num_val = int(vals[0])
                    grade_val = float(str(vals[1]).replace(',', '.'))
                    if 0.0 <= grade_val <= 10.0:
                        imported_grades[num_val] = grade_val
                except (ValueError, TypeError):
                    continue
        st.sidebar.success(f"Notas importadas para {len(imported_grades)} alunos!")
    except Exception as e:
        st.sidebar.error(f"Erro ao ler arquivo: {e}")

# Montagem dos Dados da Turma Selecionada
students = turmas_data[turma_selecionada]["students"]

table_data = []
for st_item in students:
    num = st_item["num"]
    nome = st_item["nome"]
    n1 = st_item["n1_grades"].get(disciplina_selecionada, None)
    meta = calc_nota_minima(n1)
    
    # Nota inicial: importada ou padrão vazia
    default_n2 = imported_grades.get(num, None)
    
    table_data.append({
        "num": num,
        "coc": st_item.get("coc", ""),
        "nome": nome,
        "n1": n1,
        "n1_str": f"{float(n1):.1f}" if isinstance(n1, (int, float)) else "(*)",
        "meta": meta,
        "n2": default_n2
    })

df_display = pd.DataFrame(table_data)

# Grid de Edição Interativa
st.subheader(f"📋 Lista de Estudantes — Turma {turma_selecionada} • {disciplina_selecionada}")

# Edição das notas de N2 via data_editor do Streamlit
edited_df = st.data_editor(
    df_display[["num", "nome", "n1_str", "meta", "n2"]],
    column_config={
        "num": st.column_config.NumberColumn("Nº", disabled=True, width="small"),
        "nome": st.column_config.TextColumn("Nome do Estudante", disabled=True, width="large"),
        "n1_str": st.column_config.TextColumn("1ª Cert. (N1)", disabled=True, width="small"),
        "meta": st.column_config.NumberColumn("🎯 Meta N2", disabled=True, format="%.1f", width="small"),
        "n2": st.column_config.NumberColumn("Nota 2ª Cert. (N2)", min_value=0.0, max_value=10.0, step=0.1, format="%.1f", width="medium")
    },
    hide_index=True,
    use_container_width=True
)

# Cálculo em tempo real dos Resultados e Estatísticas
results_list = []
total_lancadas = 0
total_aprovados = 0
total_finais = 0
soma_mf = 0.0

for idx, row in edited_df.iterrows():
    num = row["num"]
    nome = row["nome"]
    n1_raw = df_display.loc[idx, "n1"]
    meta = row["meta"]
    n2_val = row["n2"]
    
    if pd.isna(n2_val):
        n2_calc = "(*)"
        mf = None
        status = "—"
    else:
        n2_calc = round(float(n2_val), 1)
        mf = calc_media_final(n1_raw, n2_calc)
        total_lancadas += 1
        if mf is not None:
            soma_mf += mf
            if mf >= 6.0:
                total_aprovados += 1
                status = "🟢 APROVADO DIRETO"
            else:
                total_finais += 1
                status = "🔴 PROVA FINAL"
        else:
            status = "—"
            
    results_list.append({
        "num": num,
        "coc": df_display.loc[idx, "coc"],
        "nome": nome,
        "n1": n1_raw,
        "meta_n2": meta,
        "n2": n2_calc,
        "mf": mf,
        "status": status
    })

# Painel de Indicadores Resumo
col1, col2, col3, col4, col5 = st.columns(5)
col1.metric("Total de Alunos", len(students))
col2.metric("Notas Lançadas", total_lancadas)
col3.metric("Aprovados Direto", total_aprovados)
col4.metric("Em Prova Final", total_finais)
col5.metric("Média da Turma", f"{soma_mf / total_lancadas:.1f}" if total_lancadas > 0 else "-")

st.write("---")

# Botão de Download da Planilha Oficial de 2 Colunas
planilha_excel = gerar_planilha_2_colunas(turma_selecionada, disciplina_selecionada, results_list)

col_btn1, col_btn2 = st.columns([2, 3])
with col_btn1:
    st.download_button(
        label=f"💾 Baixar Planilha de Envio ({turma_selecionada}_{disciplina_selecionada}.xlsx)",
        data=planilha_excel,
        file_name=f"{turma_selecionada}_{disciplina_selecionada}.xlsx",
        mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        use_container_width=True
    )
with col_btn2:
    st.caption("A planilha gerada possui rigorosamente **2 colunas** (Nº e Disciplina) com o cabeçalho oficial para importação pela direção/secretaria.")
